COMMAND.ACTION:
if test -n "${intfName}"; then
python3 $SONIC_CLI_ROOT/sonic_cli_if.py get_openconfig_relay_agent_relay_agent_dhcpv6_interfaces_interface_state show_ipv6_dhcp_relay_statistics.j2 ${intfName}
elif test -n "${vlanName}"; then
python3 $SONIC_CLI_ROOT/sonic_cli_if.py get_openconfig_relay_agent_relay_agent_dhcpv6_interfaces_interface_state show_ipv6_dhcp_relay_statistics.j2 ${vlanName}
elif test -n "${pchName}"; then
python3 $SONIC_CLI_ROOT/sonic_cli_if.py get_openconfig_relay_agent_relay_agent_dhcpv6_interfaces_interface_state show_ipv6_dhcp_relay_statistics.j2 ${pchName}
elif test -n "${brief}"; then
python3 $SONIC_CLI_ROOT/sonic_cli_if.py get_openconfig_relay_agent_relay_agent_dhcpv6 show_ipv6_dhcp_relay_brief.j2
elif test -n "${intfName1}"; then
python3 $SONIC_CLI_ROOT/sonic_cli_if.py get_openconfig_relay_agent_relay_agent_detail_dhcpv6 show_ipv6_dhcp_relay_detailed.j2 ${intfName1}
elif test -n "${vlanName1}"; then
python3 $SONIC_CLI_ROOT/sonic_cli_if.py get_openconfig_relay_agent_relay_agent_detail_dhcpv6 show_ipv6_dhcp_relay_detailed.j2 ${vlanName1}
elif test -n "${pchName1}"; then
python3 $SONIC_CLI_ROOT/sonic_cli_if.py get_openconfig_relay_agent_relay_agent_detail_dhcpv6 show_ipv6_dhcp_relay_detailed.j2 ${pchName1}
elif test -n "${detailed}"; then
python3 $SONIC_CLI_ROOT/sonic_cli_if.py get_openconfig_relay_agent_relay_agent_detail_dhcpv6 show_ipv6_dhcp_relay_detailed.j2
fi
